const theta = P.theta;    // radians
const scale = 28;         // px per unit
const R = r*scale;
// animated sweep angle from 0 to theta to "fill" the sector
const fill = (0.5 + 0.5*Math.sin(t*0.6)); // 0..1
const sweep = theta*fill;
const a0 = -0.3;          // starting angle
// full circle outline
H.circle(cx, cy, R, { stroke: H.colors.grid, width: 2 });
H.circle(cx, cy, 4, { fill: H.colors.sub });
// shaded sector (fan) up to swept angle
const fan = [[cx,cy]];
for (let i=0;i<=48;i++){ const a = a0 + sweep*i/48; fan.push([cx+R*Math.cos(a), cy+R*Math.sin(a)]); }
fan.push([cx,cy]);
H.path(fan, { color: H.colors.accent, width: 1.5, fill: "rgba(124,196,255,0.28)", close: true });
// two radii at full theta
const eAx = cx+R*Math.cos(a0), eAy = cy+R*Math.sin(a0);
const eBx = cx+R*Math.cos(a0+theta), eBy = cy+R*Math.sin(a0+theta);
H.line(cx, cy, eAx, eAy, { color: H.colors.accent2, width: 2.5 });
H.line(cx, cy, eBx, eBy, { color: H.colors.accent2, width: 2.5 });
// highlight the swept arc edge (arc length)
const arc = [];
for (let i=0;i<=48;i++){ const a = a0 + sweep*i/48; arc.push([cx+R*Math.cos(a), cy+R*Math.sin(a)]); }
H.path(arc, { color: H.colors.yellow, width: 5 });
